select grantee, table_name, privilege_type from information_schema.table_privileges where table_schema='api' order by 2,1;
select tablename, policyname, roles, cmd, qual, with_check from pg_policies;
select relname, relrowsecurity, relforcerowsecurity, relowner::regrole from pg_class where relnamespace='api'::regnamespace and relkind in ('r','v');
select * from api.app_user;
select rolname, rolbypassrls from pg_roles where rolname in ('fund_admin','expert','applicant','lawyer','anon','authenticator');
\df api.*
select tgname, tgrelid::regclass from pg_trigger where not tgisinternal;

select * from api.status;
\df priv.*
select pg_get_functiondef('priv.my_company'::regproc);
select grantee, table_name, column_name, privilege_type from information_schema.column_privileges where table_schema='api' and grantee in ('applicant','expert') and table_name='application';
select has_schema_privilege('lawyer','api','usage'), has_schema_privilege('applicant','api','usage'), has_schema_privilege('applicant','priv','usage');
select c.relname, c.relkind, c.reloptions from pg_class c where relnamespace='api'::regnamespace;

begin;
create table api.contract(
 id serial primary key,
 number text not null unique,
 application_id integer not null references api.application(id) on delete restrict,
 amount numeric not null check (amount>0),
 signed_on date not null default current_date,
 status text not null default 'Проект' check (status in ('Проект','Подписан'))
);
create or replace function priv.check_contract() returns trigger language plpgsql security definer set search_path=api as $$
begin
 if not exists(select 1 from api.application where id=new.application_id and status_id=priv.status_id('Одобрена')) then
  raise exception 'Договор можно заключить только по одобренной заявке';
 end if;
 return new;
end$$;
create trigger contract_check before insert or update on api.contract for each row execute function priv.check_contract();
alter table api.contract enable row level security;
create policy admin_all on api.contract for all to fund_admin using(true) with check(true);
create policy lawyer_all on api.contract for all to lawyer using(true) with check(true);
create policy applicant_read on api.contract for select to applicant using (exists(select 1 from api.application a where a.id=application_id and a.company_id=priv.my_company()));
grant select,insert,update,delete on api.contract to fund_admin;
grant select,insert,update on api.contract to lawyer;
grant select on api.contract to applicant;
grant usage on sequence api.contract_id_seq to fund_admin, lawyer;
grant usage on schema api to lawyer;
grant select on api.company, api.status to lawyer;
grant select on api.application to lawyer;
create policy lawyer_read on api.application for select to lawyer using(true);
update api.app_user set role='lawyer' where login='lawyer1';
create view api.limit_balance with (security_invoker=true) as
select c.name as company, c.funding_limit,
  sum(a.amount) as approved,
  coalesce((select sum(k.amount) from api.contract k join api.application a2 on a2.id=k.application_id where a2.company_id=c.id),0) as contracted,
  c.funding_limit - coalesce((select sum(k.amount) from api.contract k join api.application a2 on a2.id=k.application_id where a2.company_id=c.id),0) as remaining
from api.company c join api.application a on a.company_id=c.id and a.status_id=priv.status_id('Одобрена')
group by c.id,c.name,c.funding_limit;
grant select on api.limit_balance to fund_admin, lawyer, applicant;
commit;
select id,number,company_id,amount from api.application where status_id=20003;
